-- win95 keeps its curated Norsys layout/colours from the
-- examples_win95 module; merge it in like the repo does
do
    local ok, win95 = pcall(require, "server.lua.examples_win95")
    if ok and type(win95) == "table" and win95.model then
        EXAMPLES.models[win95.name] = { key = win95.key, model = win95.model }
    end
end
return EXAMPLES
